#[cfg(test)]
mod cpu_meter {
    use super::*;
    use crate::executor_allocation_meter as meter;
    #[test]
    fn native_reads() {
        let cancel = Cancellation::default();
        let mut source = Source::default();
        meter::start();
        let first = source.sample(&cancel).unwrap();
        for _ in 0..200 {
            let reading = source.sample(&cancel).unwrap();
            assert_eq!(first.total, reading.total);
            assert!(reading.cores > 0 && reading.used <= reading.total && (0.0..=100.0).contains(&reading.cpu));
        }
        let counts = meter::stop();
        assert_eq!(counts.allocations, 0);
        assert_eq!(counts.live, 0);
        eprintln!("CPU_ALLOC native reads=201 state_bytes={} allocations={} peak={} final={}", std::mem::size_of::<Source>(), counts.allocations, counts.peak, counts.live);
    }
    #[test]
    fn bounded_linux_inputs() {
        use std::io::Read;
        let cancel = Cancellation::default();
        let mut cpu = [0u8; CPU_BYTES + 1];
        let mut memory = [0u8; MEMORY_BYTES + 1];
        let mut input = b"MemTotal: 100 kB\nMemAvailable: 25 kB\n".to_vec();
        input.resize(MEMORY_BYTES, b' ');
        meter::start();
        let reader = (&b"cpu 10 20 30 40 50 60 70 80 100 100\n"[..]).chain(std::io::repeat(b'x'));
        let ticks = parse_cpu(read_text(reader, &mut cpu, true, &cancel).unwrap(), 1_000_000).unwrap();
        assert_eq!(ticks.cores, 1_000_000);
        assert_eq!((ticks.busy, ticks.idle), (270,90));
        assert_eq!(parse_memory(read_text(input.as_slice(), &mut memory, false, &cancel).unwrap()), Some((75*1024,100*1024)));
        assert!(read_text(std::io::repeat(b'x'), &mut memory, false, &cancel).is_none());
        let counts = meter::stop();
        assert_eq!(counts.allocations, 0);
        assert_eq!(counts.live, 0);
        eprintln!("CPU_ALLOC input modeled_cores=1000000 cpu_cap={} memory_cap={} allocations={} peak={} final={}", CPU_BYTES, MEMORY_BYTES, counts.allocations, counts.peak, counts.live);
    }
}
